function validate_cascade()
P=sim_config();D=load(fullfile(P.results,'design_gains.mat'));C=[D.C([1 2 4]),D.Strict];T=table();for j=1:numel(C)
 c=C(j);M=chan_model_inner(c.kind,c.G(1:6)',D.S.Ts,c.G(19:24)',D.S.act,[],[c.tauhat c.ndhat]);Q=chan_model(c.kind,c.G(1:6)',D.S.Ts,c.G(19:24)',D.S.act,[],[c.tauhat c.ndhat]);assert(isequal(M.A,Q.A)&&isequal(M.B,Q.B));k=M.keep;F=M.A(k,k);B=M.B(k,2:5);ci=M.Ci(k);di=M.Di(2:5);W=diag([D.S.sy(1)^2,D.S.sv(1)^2,D.S.sy(3)^2,D.S.sv(3)^2]);Fa=[F zeros(numel(k),1);ci 0];Ba=[B;di];Ca=[ci -1];Pa=dlyap(Fa,Ba*W*Ba');ind=Ca*Pa*Ca'+di*W*di';z=cascade_stats(c,D.S);err=abs(ind-z(4)^2)/max(ind,eps);assert(err<1e-8);T=[T;table(string(c.name),err,'VariableNames',{'Ctrl','IndependentIncrementRelativeError'})];end;writetable(T,fullfile(P.results,'cascade_covariance.csv'));
K=readtable(fullfile(P.results,'cascade_noise.csv'),'TextType','string');H=readtable(fullfile(P.results,'hover_per_seed.csv'),'TextType','string');V=table();for j=1:height(K),a=H(H.Ctrl==K.Ctrl(j),:);cap=K.CascadeCap(j);for axis=1:2,v=a.MeasuredSigmaDU;if axis==2,v=a.PitchMeasuredSigmaDU;end;ci=tinv(.975,9)*std(v)/sqrt(10);V=[V;table(K.Ctrl(j),axis,mean(v),ci,cap,mean(v)+ci<=cap,'VariableNames',{'Ctrl','Axis','MeanSigmaDU','CI95HalfWidth','CascadeCap','UpperCIWithinCap'})];end,end;assert(all(V.UpperCIWithinCap(V.Ctrl~="PID-Budget")));writetable(V,fullfile(P.results,'hover_confidence.csv'));fprintf('CASCADE_INDEPENDENT_AND_HOVER_CI_PASS\n');
end
